mapper.select:
select 
from collection_event
where municipality_id = #{municipalityId}
  and collection_date between #{startDate} and #{endDate}
  and (sector = #{sector} or sector = 'all')
order by collection_date asc, collection_type asc

mapper.delete:
delete from collection_event
where municipality_id = #{municipalityId}
  and auto_generated = true
  and collection_date >= #{from}

mapper.select:
select 
from collection_event
where municipality_id = #{municipalityId}
  and collection_date >= #{startDate}
order by collection_date asc, collection_type asc, id asc
limit #{limit}
